style.css:
@-moz-document domain("youtube.com") {
/* Main colors */
  :root {
    --yt-spec-base-background: #0b0b0f !important;
    --yt-spec-raised-background: #141219 !important;
    --yt-spec-menu-background: #18141d !important;
    --yt-spec-general-background-a: #0b0b0f !important;
    --yt-spec-general-background-b: #141219 !important;
    --yt-spec-general-background-c: #211923 !important;

    --yt-spec-text-primary: #ffe6f1 !important;
    --yt-spec-text-secondary: #c6a9ba !important;
    --yt-spec-call-to-action: #ff69b4 !important;
    --yt-spec-themed-blue: #ff8ac4 !important;

    --yt-spec-10-percent-layer: #ff69b422 !important;
    --yt-spec-brand-background-solid: #ff69b4 !important;
  }

  /* Page backgrounds */
  html,
  body,
  ytd-app,
  #content,
  ytd-watch-flexy,
  #primary,
  #secondary,
  ytd-browse,
  ytd-two-column-browse-results-renderer {
    background-color: #0b0b0f !important;
  }

  /* Header */
  #masthead,
  ytd-masthead,
  #container.ytd-masthead {
    background: #0b0b0f !important;
  }

  /* Logo accent */
  .yt-spec-icon-shape,
  #logo-icon,
  yt-icon {
    --iron-icon-fill-color: #ff69b4;
  }

  /* Search bar */
  #container.ytd-searchbox {
    background: #141219 !important;
    border: 1px solid #493043 !important;
    border-radius: 24px !important;
  }

  #search-input input,
  #searchbox input {
    color: #ffe6f1 !important;
    caret-color: #ff69b4 !important;
  }

  ytd-searchbox[has-focus] #container.ytd-searchbox {
    border-color: #ff69b4 !important;
  }

  /* Text */
  h1, h2, h3,
  #video-title,
  #channel-name,
  yt-formatted-string,
  #content-text {
    color: #ffe6f1;
  }

  /* Pink links */
  a:hover,
  #video-title:hover,
  #channel-name:hover {
    color: #ff69b4 !important;
  }

  /* Buttons */
  ytd-button-renderer #button,
  yt-button-shape button,
  ytd-toggle-button-renderer #button {
    border-radius: 20px !important;
  }

  yt-button-shape button:hover,
  ytd-button-renderer #button:hover {
    background-color: #ff69b422 !important;
  }

  /* Subscribe button */
  ytd-subscribe-button-renderer button,
  ytd-subscribe-button-renderer yt-button-shape button {
    background: #ff69b4 !important;
    color: #180b13 !important;
    border-radius: 20px !important;
  }

  /* Sidebar */
  #guide-content,
  ytd-mini-guide-renderer,
  ytd-guide-renderer,
  ytd-guide-entry-renderer {
    background: #0b0b0f !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: #ff69b422 !important;
    border-radius: 12px !important;
  }

  /* Selected sidebar items */
  ytd-guide-entry-renderer[active] {
    background: #ff69b426 !important;
    border-radius: 12px !important;
  }

  /* Video cards */
  ytd-rich-item-renderer,
  ytd-compact-video-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer {
    border-radius: 12px !important;
  }

  /* Category chips */
  yt-chip-cloud-chip-renderer {
    background: #19141e !important;
    border-radius: 10px !important;
  }

  yt-chip-cloud-chip-renderer[selected],
  yt-chip-cloud-chip-renderer:hover {
    background: #ff69b4 !important;
    color: #180b13 !important;
  }

  /* Progress bars */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: #ff69b4 !important;
  }

  .ytp-volume-slider-handle,
  .ytp-scrubber-button {
    background: #ff69b4 !important;
  }

  /* Menus and pop-ups */
  ytd-popup-container,
  tp-yt-iron-dropdown,
  ytd-menu-popup-renderer,
  tp-yt-paper-listbox {
    background: #18141d !important;
    color: #ffe6f1 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 9px;
  }

  ::-webkit-scrollbar-track {
    background: #0b0b0f;
  }

  ::-webkit-scrollbar-thumb {
    background: #573449;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #ff69b4;
  }

  /* Subtle pink selection */
  ::selection {
    background: #ff69b4;
    color: #180b13;
  }
}
